const jiraBrand = $('Jira > Get Issue').item.json.fields?.customfield_11504?.[0]?.value;
const jiraRegion = $('Jira > Get Issue').item.json.fields?.customfield_11507?.[0]?.value;

const row = $('Get Row from Baserow').item.json;

if (!row || !row.brandCode) {
  throw new Error(`No Baserow configuration found for Brand: ${jiraBrand}, Region: ${jiraRegion}`);
}

const baseName = $('Naming Conventions API').item.json.name;
const baseSlug = $('Naming Conventions API').item.json.slug;
const runSuffix = Date.now().toString().slice(-4);

return {
  sessionId: $('CMS & MM Login').item.json.sessionId,
  name: `${baseName} ${runSuffix}`,
  slug: `${baseSlug}-${runSuffix}`,
  region: row.region || jiraRegion,
  regionId: row.regionId,
  brandName: row.brandName,
  brandCode: row.brandCode,
  bucket: row.bucket,
  territory: row.territory,
  pageUrl: row.pageUrl
};

