const brand = $('OSN Static Fields Mapping').item.json.brandCode;
const region = $('OSN Static Fields Mapping').item.json.region;
const row = $('Get Row from Baserow').item.json;

const playerId = row.PLAYER_ID;
const audienceCode = row.AUDIENCE_CODE;

if (!playerId || !audienceCode) {
  throw new Error(`PLAYER_ID or AUDIENCE_CODE missing in Baserow for ${brand}-${region}`);
}

const csvContent = `AUDIENCE_CODE,PLAYER_ID\n${audienceCode},${playerId}`;

return {
  json: {
    fileName: `${brand}-${region}.csv`
  },
  binary: {
    audience_csv: {
      data: btoa(csvContent),
      mimeType: 'text/csv',
      fileName: `${brand}-${region}.csv`
    }
  }
};

