const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export default async ({ page, context }) => {
  await page.setViewport({ width: 1440, height: 750 });
  const screenshots = [];

  const takeScreenshot = async (stepName) => {
    const base64 = await page.screenshot({ encoding: 'base64' });
    screenshots.push({
      step: stepName,
      url: page.url(),
      image: base64
    });
  };

  const domain = context.domain;

  // Step 1: Initial state before injecting cookies or navigating
  await takeScreenshot('1_initial_state');

  // Step 2: Set session cookies
  await page.setCookie(
    { name: 'sessionId', value: context.sessionId, domain: domain, path: '/' },
    { name: 'sid', value: context.sessionId, domain: domain, path: '/' }
  );

  // Step 3: Fast navigation with DOM Content Loaded and 15s timeout
  try {
    await page.goto(context.url, { waitUntil: 'domcontentloaded', timeout: 18000 });
  } catch (err) {
    console.log('Navigation timeout or error:', err.message);
  }
  await takeScreenshot('2_after_goto');

  // Step 4: Force active tab visibility and window focus
  await page.bringToFront();
  await page.evaluate(() => {
    Object.defineProperty(document, 'hidden', { value: false, writable: true });
    Object.defineProperty(document, 'visibilityState', { value: 'visible', writable: true });
    document.dispatchEvent(new Event('visibilitychange'));
    window.dispatchEvent(new Event('focus'));
  });

  // Step 5: Simulate physical user interaction (mouse move and scroll)
  await page.mouse.move(500, 300);
  await page.mouse.wheel({ deltaY: 100 });
  await sleep(300);
  await page.mouse.wheel({ deltaY: -100 });
  await takeScreenshot('3_after_user_interaction');

  // Step 6: Non-blocking check for notification selector with 5s timeout
  try {
    await page.waitForSelector(
      'div.ol-notification__root, .ol-toast, [role="alert"], .ol-modal, div.ol-z_docked',
      { visible: true, timeout: 7000 }
    );
    await takeScreenshot('4_popup_detected');
  } catch (err) {
    console.log('Popup selector not detected within timeout');
    await takeScreenshot('4_popup_timeout');
  }

  // Step 7: Final settling pause before final screenshot
  await sleep(1500);
  await takeScreenshot('5_final_capture');

  return {
    data: {
      totalSteps: screenshots.length,
      stepsSummary: screenshots.map(s => ({ step: s.step, url: s.url })),
      screenshot: screenshots[screenshots.length - 1].image,
      allScreenshots: screenshots
    },
    type: 'application/json'
  };
};

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export default async ({ page, context }) => {
  await page.setViewport({ width: 1440, height: 750 });

  const domain = context.domain;

  await page.setCookie(
    { name: 'sessionId', value: context.sessionId, domain: domain, path: '/' },
    { name: 'sid', value: context.sessionId, domain: domain, path: '/' }
  );

  await page.goto(context.url, { waitUntil: 'domcontentloaded', timeout: 30000 });

  await page.waitForSelector('a.ol-responsive-button[href="/account/cashier/deposit"]', { timeout: 15000 });
  await sleep(2000);

  await page.evaluate(() => {
    const container = document.querySelector('[data-surface="accountPanelSection"]')
      || document.querySelector('[data-surface="accountPanelSubContent"]');
    const target = [...container.querySelectorAll('button.ol-tab_item')]
      .find((button) => button.textContent.includes('Notifications'));
    if (!target) throw new Error('Notifications tab was not found');
    target.click();
  });

  await page.waitForSelector('tr.ol-table__row[data-index="0"]', { timeout: 15000 });
  await sleep(2000);

  await page.evaluate(() => {
    const row = document.querySelector('tr.ol-table__row[data-index="0"]');
    if (row) {
      row.scrollIntoView({ block: 'center' });
      row.click();
    } else {
      throw new Error('First notification row was not found');
    }
  });

  await sleep(3000);

  const screenshot = await page.screenshot({ encoding: 'base64' });
  return { data: { screenshot }, type: 'application/json' };
};

